using std::cin;
using std::string;
double divide(double a, double b) {
    if (b == 0) {
        throw std::invalid_argument("zero divisor");
    }
    return a / b;
}
int main() {
try {
    cout << "A ";
    divide(8,0);
    cout << "B ";
} catch (const std::exception& e) {
    cout << "C ";
}
cout << "D\n";
}

