#include <iostream>
#include <string>
#include <stdexcept>
using std::cout;
using std::cin;
using std::string;

class Score {
    int value_;
public:
    explicit Score(int value) : value_(value) {}
    int get() const { return value_; }
};
void print(const Score& score) {
    cout << score.get() << '\n';
}
int main() {
Score score(80); print(score);
}
